161→/**
162→ * Decide whether a parsed Bash result represents a successful asset fetch.
163→ *
164→ * Judged only on the response side: process exit status, curl's own error line,
165→ * and the bridge's `code` field. The echoed command is never consulted.
166→ */
167→export function classifyFetch(result, raw = "") {
168→  if (!result) {
169→    // The command never ran: the harness refused the tool before the shell saw it.
170→    // Distinct from a timeout, and the failure mode behind the very first Gate 0
171→    // run, where every asset curl was denied in non-interactive mode.
172→    if (/^Error: Permission to use (\w+) has been denied/.test(raw)) {
173→      return { ok: false, reason: "tool blocked by the harness before it ran" };
174→    }
175→    return { ok: false, reason: "not a Bash command result" };
176→  }
177→
178→  const curlError = /curl: \((\d+)\)\s*([^\n]*)/.exec(result.stderr);
179→  if (curlError) {
180→    return { ok: false, reason: `curl (${curlError[1]}) ${curlError[2]}`.trim() };
181→  }
182→  if (result.exitCode !== null && result.exitCode !== 0) {
183→    return { ok: false, reason: `command exited ${result.exitCode}` };
184→  }
185→  if (result.stdout.length === 0) {
186→    return { ok: false, reason: "exit 0 but no response body" };
187→  }
188→
189→  const code = /"code"\s*:\s*(-?\d+)/.exec(result.stdout);
190→  if (code && code[1] !== "0") {
191→    return { ok: false, reason: `bridge replied code=${code[1]}` };
192→  }
193→  return { ok: true, reason: code ? "exit 0, body code=0" : "exit 0, non-empty body" };
194→}
